{
  "slug": "syncora-connector-run-checklist",
  "title": "Recovering From an Interrupted Syncora Connector Run",
  "description": "Use the connector result and a known voucher to check what changed after an interrupted Windows sync.",
  "category": "Sync troubleshooting",
  "sections": [
    {
      "heading": "Capture the result of the interrupted run",
      "body": "On the accounting PC, note the company, time and exact error. Look up the last successful run to establish how old the dashboard could be. If a run is still in progress, wait for its result before deciding whether to retry."
    },
    {
      "heading": "Retry under the intended company",
      "body": "Confirm that the same company is open and available to the connector. When it is safe to try again, start one sync, wait for a result and write down the completion time. If the same error repeats, keep that message for support rather than changing several settings at once."
    },
    {
      "heading": "Use a recent transaction as the check",
      "body": "Find a voucher dated after the earlier successful sync and compare it in Syncora. Then check one older voucher to confirm the intended company is selected. If the recent one is still missing, include both run times and the reference voucher in the support request."
    }
  ],
  "relatedPaths": [
    "/guides/tally-sync-troubleshooting",
    "/support"
  ]
}
